(@g_id, 1, 'Check the set-up: the pendulum bob should hang freely on its thread from the clamp. Select the bob and click Inspect.', 'bob1', 'inspect', NULL, NULL, 'Click the brass bob, then Inspect.', 'The bob hangs freely from the clamp.', 'Select the bob and click Inspect.', 0),
(@g_id, 2, 'Check that the metre rule is positioned beside the pendulum. Select the rule and click Inspect.', 'ruler1', 'inspect', NULL, NULL, 'Click the yellow rule hanging beside the pendulum, then Inspect.', 'The metre rule is beside the pendulum, reading down from the point of suspension.', 'Select the metre rule and click Inspect.', 0),
(@g_id, 3, 'Adjust the length of the pendulum to l = 0.100 m with the length control.', 'bob1', 'move', '0.100', 0.0005, 'Use the Length l slider at the bottom of the lab.', 'l = 0.100 m.', 'Set the length to exactly 0.100 m.', 0),
(@g_id, 4, 'Measure l with the metre rule, from the point of suspension to the centre of the bob: select the rule, click Measure, click the centre of the bob, then Record.', 'ruler1', 'measure', NULL, NULL, 'Click the middle of the bob - not the thread, not the top of the bob.', 'Length measured to the centre of the bob.', 'Select the rule, click Measure, then click the centre of the bob.', 0),
(@g_id, 5, 'Displace the bob sideways through a small angle (less than 10°) and release it gently, without pushing it.', 'bob1', 'rotate', '5', 5, 'Drag the bob a little to one side - watch the angle - and let go.', 'Released from a small angle.', 'Use a small angular displacement (less than 10°) for accurate results.', 0),
(@g_id, 6, 'Let the first few oscillations pass so the swing is regular, then start the stopwatch as the bob passes the centre.', 'stopwatch1', 'switch_on', NULL, NULL, 'Wait until the oscillations are steady, then click Start.', 'Timing started.', 'Start the stopwatch now.', 0),
(@g_id, 7, 'Count 20 complete oscillations (watch the counter) and stop the stopwatch immediately after the 20th.', 'stopwatch1', 'switch_off', NULL, NULL, 'Click Stop as the counter reaches 20 / 20.', 'Stopwatch stopped after 20 oscillations.', 'Stop the stopwatch after the 20th oscillation.', 0),
